WITH "r0" AS ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND ( ( true AND ( ( true ) ) AND ( ( true ) ) ) ) ORDER BY "s"."id" ASC NULLS LAST ) SELECT row_to_json((SELECT "%" FROM (SELECT row_to_json((SELECT "%" FROM (SELECT count( "t0" .*) AS "count" , row_to_json((SELECT "%" FROM (SELECT sum( "t0"."id" ) AS "id" ) AS "%")) AS "sum" ) AS "%")) AS "aggregate" , coalesce(array_to_json((array_agg( "c1"."j" ORDER BY "t0"."id" ASC NULLS LAST ))[1: 2 ]), '[]') AS "nodes" ) AS "%")) FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" ) AS "%")) AS "j" FROM (SELECT true) AS "_" ) AS "c1" ON true
